                `  Specs: ${foundPlan.derived_specs.join(", ")}`,
              );
            }
            if (foundPlan.derived_tasks.length > 0) {
              console.log(
                `  Tasks: ${foundPlan.derived_tasks.join(", ")}`,
              );
            }
          }

          // Show content
          if (foundPlan.content) {
