/**
 * CLI Plan Import Tests
 * AC: @plan-import ac-11 through ac-33
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import {
  setupTempFixtures,
  cleanupTempDir,
  kspec as kspecRun,
  kspecOutput as kspec,
  kspecJson,
} from "./helpers/cli";

describe("Integration: plan import", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @plan-import ac-11
  it("should parse specs from ## Specs YAML block", async () => {
    const planPath = path.join(tempDir, "test-plan.md");
    await fs.writeFile(
      planPath,
      `# Test Plan

## Specs

\`\`\`yaml
- title: Feature One
  slug: feature-one
  type: feature
  description: First feature
\`\`\`
`,
    );

    const output = kspec(
      `plan import "${planPath}" --module @test-core --dry-run`,
      tempDir,
    );
    expect(output).toContain("Would create spec: @feature-one");
  });

  // AC: @plan-import ac-12
  it("should auto-derive tasks when derive_from_specs is true", async () => {
    const planPath = path.join(tempDir, "test-plan.md");
    await fs.writeFile(
      planPath,
      `# Test Plan

## Specs

\`\`\`yaml
- title: Feature One
  slug: feature-one
  type: feature
\`\`\`

## Tasks

derive_from_specs: true
`,
    );

    const output = kspec(
      `plan import "${planPath}" --module @test-core --dry-run`,
      tempDir,
    );
    expect(output).toContain("Would create spec: @feature-one");
    expect(output).toContain("Would derive task:");
    expect(output).toContain("from @feature-one");
  });

  // AC: @plan-import ac-13
  it("should add global implementation notes to plan record and reference to tasks", async () => {
    const planPath = path.join(tempDir, "test-plan.md");
    await fs.writeFile(
      planPath,
      `# Test Plan

## Specs

\`\`\`yaml
- title: Feature One
  slug: feature-one
  type: feature
\`\`\`

## Tasks

derive_from_specs: true

## Implementation Notes

Use pattern X for implementation.
Follow coding standards Y.
`,
    );

    kspec(`plan import "${planPath}" --module @test-core`, tempDir);

    // Plan record should have the global implementation notes (with plan- prefix)
    const plan = kspecJson<{ notes: Array<{ content: string }> }>(
      "plan get @plan-test-plan --json",
      tempDir,
    );
    expect(plan.notes).toHaveLength(1);
    expect(plan.notes[0].content).toContain("Implementation notes:");
    expect(plan.notes[0].content).toContain("Use pattern X");

    // Task without per-spec notes should get a reference to the plan
    const allTasks = kspecJson<Array<{ notes: Array<{ content: string }>; plan_ref: string }>>(
      "task list --json",
      tempDir,
    );
    const tasks = allTasks.filter(t => t.plan_ref === "@plan-test-plan");
    expect(tasks).toHaveLength(1);
    expect(tasks[0].notes).toHaveLength(1);
    expect(tasks[0].notes[0].content).toContain("See plan @plan-test-plan for implementation notes");
  });

  // AC: @plan-import ac-13 - Per-spec implementation notes
  it("should add per-spec implementation notes to the corresponding task only", async () => {
    const planPath = path.join(tempDir, "per-spec-notes.md");
    await fs.writeFile(
      planPath,
      `# Per Spec Notes Plan

## Specs

\`\`\`yaml
- title: Feature Alpha
  slug: feature-alpha
  type: feature
  implementation_notes: |
    Use pattern A for alpha implementation.

- title: Feature Beta
  slug: feature-beta
  type: feature
  implementation_notes: |

import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  TaskStatusSchema,
  TaskTypeSchema,
  UlidSchema,
  VcsRefSchema,
} from "./common.js";

/**
 * Automation eligibility status for tasks
 * AC: @task-automation-eligibility ac-1
 * - eligible: Task can be processed by automation loops
 * - needs_review: Task was rejected by automation and needs human review
 * - manual_only: Task should only be handled by humans
 * - undefined/absent: Task has not been assessed for automation (unassessed)
 */
export const AutomationStatusSchema = z.enum([
  "eligible",
  "needs_review",
  "manual_only",
]);

/**
 * Note entry - append-only work log
 */
export const NoteSchema = z.object({
  _ulid: UlidSchema,
  created_at: DateTimeSchema,
  author: z.string().optional(),
  content: z.string(),
  supersedes: UlidSchema.nullable().optional(),
});

/**
 * Todo item - lightweight checklist
 */
export const TodoSchema = z.object({
  id: z.number().int().positive(),
  text: z.string(),
  done: z.boolean().default(false),
  done_at: DateTimeSchema.optional(),
  added_at: DateTimeSchema,
  added_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Full task schema
 * Note: created_at defaults to now if not provided (auto-populated on load)
 */
export const TaskSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.default("task"),

  // Content (doesn't duplicate spec - brief description for standalone context)
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship (links to workflow, agent, or convention for process improvement tracking)
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship (links to the plan this task was derived from)
  // AC: @plan-derive ac-5, ac-6
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking (where this task came from)
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.default("pending"),
  blocked_by: z.array(z.string()).default([]),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).default([]),
  context: z.array(RefSchema).default([]),

  // Work metadata
  priority: z.number().int().min(1).max(5).default(3),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).default([]),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).default([]),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  started_at: DateTimeSchema.nullable().optional(),
  submitted_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).default([]),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).default([]),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2)
  // Optional - absent means unassessed
  automation: AutomationStatusSchema.optional(),
});

/**
 * Task input schema (for creating new tasks, some fields auto-generated)
 * All fields except title are optional - defaults will be applied
 */
export const TaskInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.optional(),

  // Content
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.optional(),
  blocked_by: z.array(z.string()).optional(),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).optional(),
  context: z.array(RefSchema).optional(),

  // Work metadata
  priority: z.number().int().min(1).max(5).optional(),

import { z } from "zod";
import {
  DateTimeSchema,
  ImplementationStatusSchema,
  ItemTypeSchema,
  MaturitySchema,
  PrioritySchema,
  RefSchema,
  SlugSchema,
  UlidSchema,
} from "./common.js";
import { NoteSchema } from "./task.js";

/**
 * Status block for spec items
 */
export const StatusSchema = z.object({
  maturity: MaturitySchema.default("draft"),
  implementation: ImplementationStatusSchema.default("not_started"),
});

/**
 * Acceptance criteria in Given/When/Then format
 */
export const AcceptanceCriterionSchema = z.object({
  id: z.string(),
  given: z.string(),
  when: z.string(),
  then: z.string(),
});

/**
 * Implementation traceability
 */
export const ImplementationRefSchema = z.object({
  path: z.string(),
  function: z.string().optional(),
  lines: z.string().optional(),
});

/**
 * Traceability block
 */
export const TraceabilitySchema = z.object({
  implementation: z.array(ImplementationRefSchema).optional(),
  tests: z.array(z.object({ path: z.string() })).optional(),
  commits: z.array(z.string()).optional(),
  issues: z.array(z.string()).optional(),
});

/**
 * Full spec item schema
 */
export const SpecItemSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: ItemTypeSchema.optional(),

  // Status
  status: StatusSchema.optional(),

  // Classification
  priority: PrioritySchema.optional(),
  tags: z.array(z.string()).default([]),

  // Content
  description: z.string().optional(),
  acceptance_criteria: z.array(AcceptanceCriterionSchema).optional(),

  // Relationships (references start with @)
  depends_on: z.array(RefSchema).default([]),
  implements: z.array(RefSchema).default([]),
  relates_to: z.array(RefSchema).default([]),
  tests: z.array(RefSchema).default([]),
  traits: z.array(RefSchema).default([]),
  supersedes: RefSchema.nullable().optional(),

  // Traceability
  traceability: TraceabilitySchema.optional(),

  // Lifecycle
  created: DateTimeSchema.optional(),
  created_by: z.string().optional(),
  deprecated_in: z.string().nullable().optional(),
  superseded_by: RefSchema.nullable().optional(),

  // Verification metadata (for retrospective specs)
  verified_at: DateTimeSchema.optional(),
  verified_by: RefSchema.optional(),

  // Notes (work log / implementation context)
  notes: z.array(NoteSchema).default([]),
});

/**
 * Spec item input schema (for creating new items, ULID auto-generated)
 */
export const SpecItemInputSchema = SpecItemSchema.omit({ _ulid: true }).extend({
  _ulid: UlidSchema.optional(),
});

/**
 * Spec item patch schema (partial fields, passthrough for unknown)
 * Used by `kspec item patch` for JSON updates
 */
export const SpecItemPatchSchema = SpecItemInputSchema.partial().passthrough();

/**
 * Root manifest schema
 */
export const ManifestSchema = z.object({
  kynetic: z.string().default("1.0"),
  project: z.object({
    name: z.string(),
    version: z.string().default("0.1.0"),
    status: MaturitySchema.default("draft"),
  }),

  // Inline items (small projects)
  modules: z.array(z.any()).optional(), // Recursive, define separately if needed
  features: z.array(z.any()).optional(),
  requirements: z.array(z.any()).optional(),
  constraints: z.array(z.any()).optional(),
  decisions: z.array(z.any()).optional(),
  traits: z.array(z.any()).optional(),

  // External references (large projects)
  includes: z.array(z.string()).optional(),

  // Hooks configuration
  hooks: z.record(z.string()).optional(),

  // AC: @config-manifest-cleanup ac-2 — backward compat for existing manifests with config block
  // This field is DEPRECATED — use kspec.config.yaml instead
  config: z.any().optional(),

  // AC: @config-manifest-cleanup ac-4 — backward compat for existing manifests with daemon block
  // DEPRECATED: Use kspec.config.yaml daemon settings instead
  // Kept as explicit optional for backward compat parsing (do not use .passthrough())
  daemon: z.object({
    auto_start: z.boolean().default(true),
    port: z.number().int().min(1).max(65535).default(3456),
  }).optional(),
});

export type Status = z.infer<typeof StatusSchema>;
export type AcceptanceCriterion = z.infer<typeof AcceptanceCriterionSchema>;
export type ImplementationRef = z.infer<typeof ImplementationRefSchema>;

