/**
 * Tests for plan document parser
 *
 * AC: @plan-import ac-11 - Parse ## Specs YAML blocks
 * AC: @plan-import ac-12 - Support derive_from_specs flag
 * AC: @plan-import ac-13 - Extract ## Implementation Notes
 * AC: @plan-import ac-16 - Topological ordering
 * AC: @plan-import ac-17 - Detect missing parent references
 * AC: @plan-import ac-18 - Detect circular dependencies
 * AC: @plan-import ac-21 - Handle YAML parse errors
 * AC: @plan-import ac-22 - Validate required fields
 */

import { describe, expect, it } from "vitest";
import {
  parsePlanDocument,
  topologicalSort,
  validateParentRefs,
  type PlanSpec,
} from "../src/parser/plan-document.js";
import { createSpecItem } from "../src/parser/yaml.js";

describe("Plan Document Parser", () => {
  // AC: @plan-import ac-11
  it("should parse specs from ## Specs YAML block", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- title: JSON Output Mode
  slug: json-output
  type: feature
  description: Add JSON output support

- title: CLI Traits
  slug: cli-traits
  type: requirement
  description: Common CLI behaviors
\`\`\`
`;

    const result = parsePlanDocument(plan);

    expect(result.specs).toHaveLength(2);
    expect(result.specs[0]).toMatchObject({
      title: "JSON Output Mode",
      slug: "json-output",
      type: "feature",
      description: "Add JSON output support",
    });
    expect(result.specs[1]).toMatchObject({
      title: "CLI Traits",
      slug: "cli-traits",
      type: "requirement",
    });
    expect(result.errors).toHaveLength(0);
  });

  // AC: @plan-import ac-12
  it("should parse derive_from_specs flag from ## Tasks section", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- title: Feature A
\`\`\`

## Tasks

derive_from_specs: true
`;

    const result = parsePlanDocument(plan);

    expect(result.tasks.derive_from_specs).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  // AC: @plan-import ac-13
  it("should extract ## Implementation Notes section", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- title: Feature A
\`\`\`

## Implementation Notes

Use existing patterns.
Add comprehensive tests.
`;

    const result = parsePlanDocument(plan);

    expect(result.implementationNotes).toBe(
      "Use existing patterns.\nAdd comprehensive tests.",
    );
  });

  // AC: @plan-import ac-21
  it("should handle malformed YAML in Specs section", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- title: Feature A
  invalid yaml: [unclosed
\`\`\`
`;

    const result = parsePlanDocument(plan);

    expect(result.specs).toHaveLength(0);
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0].type).toBe("yaml");
    expect(result.errors[0].message).toContain("Malformed YAML");
  });

  // AC: @plan-import ac-22
  it("should validate required title field in specs", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- slug: missing-title
  type: feature

- title: Valid Spec
\`\`\`
`;

    const result = parsePlanDocument(plan);

    expect(result.specs).toHaveLength(1);
    expect(result.specs[0].title).toBe("Valid Spec");
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0].type).toBe("validation");
    expect(result.errors[0].message).toContain("missing required field: title");
    expect(result.errors[0].specIndex).toBe(0);

/**
 * Tests for plan_ref field on Task schema
 * AC: @plan-derive ac-5, ac-6
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  setupTempFixtures,
  cleanupTempDir,
  kspec as kspecRun,
  kspecOutput as kspec,
  kspecJson,
} from "./helpers/cli";

describe("Integration: task plan_ref field", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @plan-derive ac-6 - task displays plan_ref
  it("should allow creating task with plan_ref", () => {
    // Create a plan first
    kspec(
      'plan add --title "Test Plan" --content "Plan content" --slug test-plan-1',
      tempDir,
    );

    // Create task with plan_ref
    const output = kspec(
      'task add --title "Task from Plan" --plan-ref @test-plan-1 --slug task-from-plan',
      tempDir,
    );
    expect(output).toContain("Created task:");

    // Verify plan_ref is set
    const task = kspecJson<{ plan_ref: string | null }>(
      "task get @task-from-plan --json",
      tempDir,
    );
    expect(task.plan_ref).toBeDefined();
    expect(task.plan_ref).toBe("@test-plan-1");
  });

  // AC: @plan-derive ac-6 - task get displays plan_ref
  it("should display plan_ref in task get output", () => {
    // Create plan and task
    kspec(
      'plan add --title "Test Plan" --content "Content" --slug test-plan-2',
      tempDir,
    );
    kspec(
      'task add --title "Test Task" --plan-ref @test-plan-2 --slug test-task-2',
      tempDir,
    );

    // Check task get output
    const output = kspec("task get @test-task-2", tempDir);
    expect(output).toContain("Plan ref:");
    expect(output).toContain("@test-plan-2");
  });

  it("should allow setting plan_ref with task set", () => {
    // Create plan and task
    kspec(
      'plan add --title "Test Plan" --content "Content" --slug test-plan-3',
      tempDir,
    );
    kspec('task add --title "Test Task" --slug test-task-3', tempDir);

    // Set plan_ref
    kspec("task set @test-task-3 --plan-ref @test-plan-3", tempDir);

    // Verify it was set
    const task = kspecJson<{ plan_ref: string | null }>(
      "task get @test-task-3 --json",
      tempDir,
    );
    expect(task.plan_ref).toBe("@test-plan-3");
  });

  // AC: @task-set ac-clear-ref
  it("should allow clearing plan_ref", () => {
    // Create plan and task with plan_ref
    kspec(
      'plan add --title "Test Plan" --content "Content" --slug test-plan-4',
      tempDir,
    );
    kspec(
      'task add --title "Test Task" --plan-ref @test-plan-4 --slug test-task-4',
      tempDir,
    );

    // Clear plan_ref
    kspec("task set @test-task-4 --plan-ref null", tempDir);

