    29→
    30→export type PlanSpec = z.infer<typeof PlanSpecSchema>;
    31→
    32→/**
    33→ * Manual task definition from plan document
    34→ */
    35→export const PlanTaskSchema = z.object({
    36→  title: z.string(),
    37→  slug: z.string().optional(),
    38→  priority: z.number().optional(),
    39→  description: z.string().optional(),
    40→  tags: z.array(z.string()).optional(),
    41→  spec_ref: z.string().optional(),
    42→});
    43→
    44→export type PlanTask = z.infer<typeof PlanTaskSchema>;
    45→
    46→/**
    47→ * Tasks section configuration
    48→ */
    49→export const TasksSectionSchema = z.object({
    50→  derive_from_specs: z.boolean().optional(),
    51→  additional_tasks: z.array(PlanTaskSchema).optional(),
    52→});
    53→
    54→export type TasksSection = z.infer<typeof TasksSectionSchema>;
    55→
    56→/**
    57→ * Parsed plan document structure
