import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  UlidSchema,
} from "./common.js";
import { NoteSchema } from "./task.js";

/**
 * Plan status lifecycle
 * AC: @plan-crud ac-3, ac-4
 * - draft: Initial state, editable
 * - approved: Plan reviewed and approved, ready for derivation
 * - active: Tasks have been derived from plan
 * - completed: All derived work finished
 * - rejected: Plan was rejected, terminal state
 */
export const PlanStatusSchema = z.enum([
  "draft",
  "approved",
  "active",
  "completed",
  "rejected",
]);

/**
 * Full plan schema
 * AC: @plan-crud ac-1, ac-8, ac-30
 */
export const PlanSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),

  // Content (markdown)
  content: z.string().default(""),

  // State
  status: PlanStatusSchema.default("draft"),

  // Links to derived work
  // AC: @plan-derive ac-5 - updated when tasks are derived
  derived_tasks: z.array(RefSchema).default([]),
  derived_specs: z.array(RefSchema).default([]),

  // Source tracking (if imported from file)
  // AC: @plan-import ac-24
  source_path: z.string().nullable().optional(),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  approved_at: DateTimeSchema.nullable().optional(), // AC: @plan-crud ac-3
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  // AC: @plan-crud ac-9
  notes: z.array(NoteSchema).default([]),
});

/**
 * Plan input schema (for creating new plans)
 * Most fields are optional - defaults will be applied
 */
export const PlanInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),

  // Content
  content: z.string().optional(),

  // State
  status: PlanStatusSchema.optional(),

  // Links
  derived_tasks: z.array(RefSchema).optional(),
  derived_specs: z.array(RefSchema).optional(),

  // Source tracking
  source_path: z.string().nullable().optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  approved_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes
  notes: z.array(NoteSchema).optional(),
});

/**
 * Plans file schema (collection of plans)
 * AC: @plan-crud ac-1 - stored in project.plans.yaml
 */
export const PlansFileSchema = z.object({
  kynetic_plans: z.string().default("1.0"),
  plans: z.array(PlanSchema),
});

export type PlanStatus = z.infer<typeof PlanStatusSchema>;
export type Plan = z.infer<typeof PlanSchema>;
export type PlanInput = z.infer<typeof PlanInputSchema>;
export type PlansFile = z.infer<typeof PlansFileSchema>;

/**
 * Plan import CLI command
 * AC: @plan-import ac-11 through ac-33
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import type { Command } from "commander";
import { markMutating } from "../command-annotations.js";
import {
  addChildItem,
  buildIndexes,
  createPlan,
  createSpecItem,
  createTask,
  getAuthor,
  initContext,
  loadAllTasks,
  loadPlans,
  savePlan,
  saveTask,
  updateSpecItem,
  type LoadedSpecItem,
} from "../../parser/index.js";
import {
  parsePlanDocument,
  topologicalSort,
  validateParentRefs,
  type PlanSpec,
} from "../../parser/plan-document.js";
import { commitIfShadow } from "../../parser/shadow.js";
import { normalizeRefInput } from "../../schema/index.js";
import type { PlanInput, SpecItemInput, TaskInput } from "../../schema/index.js";
import { errors } from "../../strings/index.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, info, isJsonMode, output, success, warn } from "../output.js";
import { ulid } from "ulid";

/**
 * Register plan import command
 * AC: @plan-import ac-11, ac-15, ac-32
 */
export function registerPlanImportCommand(planCommand: Command): void {
  markMutating(planCommand.command("import <path>"))
    .description("Import plan document and auto-generate specs/tasks")
    .requiredOption(
      "--module <ref>",
      "Module to add specs under (e.g., @core-module)",
    )
    .option("--dry-run", "Show what would be created without making changes")
    .option("--update", "Update existing specs instead of skipping them")
    .option("--json", "Output as JSON")
    .addHelpText(
      "after",
      `
Format:
  Plan documents use markdown with a ## Specs section containing a fenced
  YAML code block. The YAML must be wrapped in triple-backtick yaml markers:

    ## Specs
    \`\`\`yaml
    - title: My Feature
      type: feature
    \`\`\`

  Without the fenced code block, specs will not be detected.

Examples:
  $ kspec plan import ./plan.md --module @core
  $ kspec plan import ./plan.md --module @api --dry-run
  $ kspec plan import ./plan.md --module @features --update --json`,
    )
    .action(async (planPath: string, options) => {
      try {
        await importPlan(planPath, options);
      } catch (err) {
        error("Failed to import plan", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

/**
 * Import operation result
 */
interface ImportResult {
  createdSpecs: string[];
  updatedSpecs: string[];
  createdTasks: string[];
  errors: Array<{ message: string; spec?: PlanSpec }>;
  skipped: Array<{ slug: string; reason: string }>;
  planRef: string;
}

/**
 * Import plan document and create specs/tasks
 * AC: @plan-import ac-11 through ac-33
 */
async function importPlan(
  planPath: string,
  options: { module: string; dryRun?: boolean; update?: boolean },
): Promise<void> {
  // JSON mode is set by global preAction hook

  const ctx = await initContext();
  const author = getAuthor(ctx.config?.identity?.author);

  // Read plan file
  // AC: @plan-import ac-21 - Handle file read errors
  const fullPath = path.resolve(process.cwd(), planPath);
  let content: string;
  try {
    content = await fs.readFile(fullPath, "utf-8");
  } catch (err) {
    error(`Failed to read plan file: ${planPath}`, err);
    process.exit(EXIT_CODES.USAGE_ERROR);
  }

  // Parse plan document
  // AC: @plan-import ac-11, ac-12, ac-13, ac-21, ac-22
  const parsed = parsePlanDocument(content);

  // Report parsing errors
  if (parsed.errors.length > 0) {
    for (const err of parsed.errors) {
      if (err.type === "yaml") {
        // AC: @plan-import ac-21 - YAML parse errors (fatal)
        error(err.message);
        process.exit(EXIT_CODES.USAGE_ERROR);
      } else if (err.type === "validation") {
        // AC: @plan-import ac-22 - Validation errors (non-fatal, add to warnings)
        warn(err.message);
      }
    }
  }

  // Load plans for cross-namespace slug safety
  const plans = await loadPlans(ctx);

  // Build indexes to check existing specs (include plans for cross-namespace slug safety)
  const { refIndex, items } = await buildIndexes(ctx, plans);
  const existingSpecRefs = new Set<string>();
  for (const item of items) {
    for (const slug of (item as LoadedSpecItem).slugs || []) {
      existingSpecRefs.add(slug);
    }
    existingSpecRefs.add(item._ulid.slice(0, 8));
  }

  // Resolve module reference
  const moduleResult = refIndex.resolve(options.module);
  if (!moduleResult.ok) {
    error(errors.reference.itemNotFound(options.module));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  const moduleItem = moduleResult.item as LoadedSpecItem;

  // Verify it's a module
  if (moduleItem.type !== "module") {
    error(`${options.module} is not a module (type: ${moduleItem.type})`);
    process.exit(EXIT_CODES.USAGE_ERROR);
  }

  // Validate parent references
  // AC: @plan-import ac-17, ac-33
  const parentErrors = validateParentRefs(parsed.specs, existingSpecRefs);
  parsed.errors.push(...parentErrors);

  // Sort specs topologically
  // AC: @plan-import ac-16, ac-18
  const { sorted, error: sortError } = topologicalSort(parsed.specs);
  if (sortError) {
    // AC: @plan-import ac-18 - Circular dependency detection
    error(sortError.message);
    process.exit(EXIT_CODES.USAGE_ERROR);
  }

  // Create plan record
  // AC: @plan-import ac-24, ac-28
  // Auto-namespace plan slugs with "plan-" prefix to prevent collision with spec slugs
  // Ensure uniqueness across all namespaces (plans + specs + tasks via refIndex)
  let planSlug = `plan-${generateSlug(parsed.title)}`;
  let counter = 1;
  const baseSlug = planSlug;
  while (!refIndex.isSlugAvailable(planSlug)) {
    planSlug = `${baseSlug}-${counter}`;
    counter++;
  }

  // Track all slugs created during this import (refIndex is stale after mutations)
  const importReservedSlugs = new Set<string>([planSlug]);

  const planInput: PlanInput = {
    title: parsed.title,
    content: parsed.content,
    status: "active",
    slugs: [planSlug],
    source_path: fullPath,
  };

  const newPlan = createPlan(planInput);
  const planRef = `@${planSlug}`;

  // AC: @plan-import ac-13 - Attach global implementation notes to plan record
  if (parsed.implementationNotes) {
    newPlan.notes.push({
      _ulid: ulid(),
      created_at: new Date().toISOString(),
      author,
      content: `Implementation notes:\n\n${parsed.implementationNotes}`,
    });
  }

  // Initialize result
  const result: ImportResult = {
    createdSpecs: [],
    updatedSpecs: [],
    createdTasks: [],
    errors: [],
    skipped: [],
    planRef,
  };

  // Add parser validation errors to result
  // AC: @plan-import ac-22, ac-29 - Include parser validation errors in summary
  for (const err of parsed.errors) {
    if (err.type === "validation") {
      result.errors.push({ message: err.message });
    }
  }

  // Track newly created specs for parent resolution
  // AC: @plan-import ac-16 - Resolve local references
  const createdSpecsMap = new Map<string, LoadedSpecItem>();

  // Process specs
  // AC: @plan-import ac-14, ac-16, ac-17, ac-22, ac-23, ac-25, ac-26, ac-29
  for (let i = 0; i < sorted.length; i++) {
    const spec = sorted[i];
    try {
      // Validate required fields first
      // AC: @plan-import ac-22
      if (!spec.title) {
        const errMsg = `Spec at index ${i} missing required field: title`;
        warn(errMsg);
        result.errors.push({ message: errMsg, spec });
        continue;
      }

      const specSlug = spec.slug || generateSlug(spec.title);
      const specRef = `@${specSlug}`;

      // Check against slugs reserved during this import (plan slug, earlier specs)
      if (importReservedSlugs.has(specSlug)) {
        warn(`Spec slug "${specSlug}" collides with another item in this import, skipping`);
        result.skipped.push({ slug: specSlug, reason: "Slug collision within import" });
        continue;
      }

      // Check if spec already exists in pre-import state
      const exists = refIndex.resolve(specRef);

      if (exists.ok && !options.update) {
        // AC: @plan-import ac-14, ac-25 - Skip existing specs
        warn(`Skipping existing spec: ${specRef}`);
        result.skipped.push({ slug: specSlug, reason: "Already exists" });
        continue;
      }

      if (exists.ok && options.update) {
        // AC: @plan-import ac-26 - Update existing spec
        // Updates: description, type, tags, traits, and acceptance_criteria
        const existingSpec = exists.item as LoadedSpecItem;

        if (options.dryRun) {
          info(`Would update spec: ${specRef}`);
          result.updatedSpecs.push(specRef);
        } else {
          // Build updates from plan spec
          const updates: Partial<SpecItemInput> = {};

          if (spec.description !== undefined) {
            updates.description = spec.description;
          }
          if (spec.type !== undefined) {
            updates.type = spec.type as SpecItemInput["type"];
          }
          if (spec.traits !== undefined) {
            updates.traits = spec.traits.map(normalizeRefInput);
          }
          if (spec.depends_on !== undefined) {
            updates.depends_on = spec.depends_on.map(normalizeRefInput);
          }
          if (spec.acceptance_criteria !== undefined) {
            updates.acceptance_criteria = spec.acceptance_criteria;
          }

          await updateSpecItem(ctx, existingSpec, updates);
          info(`Updated spec: ${specRef}`);
          result.updatedSpecs.push(specRef);
        }
        continue;
      }

      // Resolve parent reference
      // AC: @plan-import ac-16, ac-17
      let parent: LoadedSpecItem | null = null;
      if (spec.parent) {
        const parentRef = normalizeRefInput(spec.parent);

        // Check if parent was just created in this import
        const parentSlug = parentRef.slice(1);
        if (createdSpecsMap.has(parentSlug)) {
          parent = createdSpecsMap.get(parentSlug)!;
        } else {
          // Check existing specs
          const parentResult = refIndex.resolve(parentRef);

          if (!parentResult.ok) {
            // AC: @plan-import ac-17, ac-33 - Missing parent with hint
            const errMsg = `Parent ${parentRef} not found. Check parent exists or define it earlier in plan`;
            warn(errMsg);
            result.errors.push({ message: errMsg, spec });
            result.skipped.push({ slug: specSlug, reason: "Missing parent" });
            continue;
          }

          parent = parentResult.item as LoadedSpecItem;
        }
      }

      // Determine if this is a root-level trait (type: trait with no parent)
      const isRootTrait = (spec.type === "trait") && !parent;

      if (options.dryRun) {
        // AC: @plan-import ac-15 - Dry run mode
        info(
          `Would create spec: ${specRef} ${spec.parent ? `under ${spec.parent}` : isRootTrait ? "(project-level trait)" : "(root)"}`,
        );
        result.createdSpecs.push(specRef);
        importReservedSlugs.add(specSlug);

        // Track would-be created spec for parent resolution in dry-run
        // AC: @plan-import ac-35 - Map depends_on in dry-run too
        const dryRunSpec = createSpecItem({
          title: spec.title,
          type: (spec.type as any) || "feature",
          slugs: [specSlug],
          description: spec.description,
          ...(spec.acceptance_criteria ? { acceptance_criteria: spec.acceptance_criteria } : {}),
          priority: undefined,
          tags: [],
          depends_on: (spec.depends_on || []).map(normalizeRefInput),
          implements: [],
          relates_to: [],
          tests: [],
          traits: (spec.traits || []).map(normalizeRefInput),
          notes: [],
        }) as LoadedSpecItem;
        createdSpecsMap.set(specSlug, dryRunSpec);
      } else {
        // Create spec item
        // AC: @plan-import ac-35 - Map depends_on to spec depends_on
        const specInput: SpecItemInput = {
          title: spec.title,
          type: (spec.type as any) || "feature",
          slugs: [specSlug],
          description: spec.description,
          priority: undefined,
          tags: [],
          depends_on: (spec.depends_on || []).map(normalizeRefInput),
          implements: [],
          relates_to: [],
          tests: [],
          traits: (spec.traits || []).map(normalizeRefInput),
          notes: [],
        };

        // Add acceptance criteria if present
        if (spec.acceptance_criteria) {
          specInput.acceptance_criteria = spec.acceptance_criteria;
        }

        const newSpec = createSpecItem(specInput);

        if (isRootTrait) {
          // Traits without a parent go to kynetic.yaml project-level traits array,
          // not the module-level traits array (same logic as `kspec trait add`)
          if (!ctx.manifestPath) {
            throw new Error("Could not find kynetic.yaml");
          }

          const { readYamlFile, writeYamlFilePreserveFormat } = await import(
            "../../parser/yaml.js"
          );
          const manifest = await readYamlFile<Record<string, unknown>>(
            ctx.manifestPath,
          );

          if (!manifest) {
            throw new Error("Could not load kynetic.yaml");
          }

          // Ensure traits array exists at root
          if (!Array.isArray(manifest.traits)) {
            manifest.traits = [];
          }

          // Strip metadata from newSpec (_sourceFile, _path)
          const { _sourceFile, _path, ...cleanItem } = newSpec as LoadedSpecItem;
          (manifest.traits as unknown[]).push(cleanItem);
          await writeYamlFilePreserveFormat(ctx.manifestPath, manifest);

          const traitIndex = (manifest.traits as unknown[]).length - 1;
          const createdSpec: LoadedSpecItem = {
            ...newSpec,
            _sourceFile: ctx.manifestPath,
            _path: `traits[${traitIndex}]`,
          } as LoadedSpecItem;
          createdSpecsMap.set(specSlug, createdSpec);
        } else {
          // Add spec to parent (or module if no parent)
          const actualParent = parent || moduleItem;
          const addResult = await addChildItem(ctx, actualParent, newSpec);

          // Track the created spec for parent resolution
          // Need to construct LoadedSpecItem with _sourceFile and _path for nested specs
          const createdSpec: LoadedSpecItem = {
            ...(addResult.item as LoadedSpecItem),
            _sourceFile: actualParent._sourceFile,
            _path: addResult.path,
          };
          createdSpecsMap.set(specSlug, createdSpec);
        }

        result.createdSpecs.push(specRef);
        importReservedSlugs.add(specSlug);
        newPlan.derived_specs.push(specRef);

        info(`Created spec: ${specRef}`);
      }
    } catch (err) {
      const errMsg = `Failed to create spec "${spec.title}": ${err instanceof Error ? err.message : String(err)}`;
      warn(errMsg);
      result.errors.push({ message: errMsg, spec });
    }
  }

  // Derive tasks from specs
  // AC: @plan-import ac-12, ac-13, ac-19, ac-20, ac-35
  if (parsed.tasks.derive_from_specs && result.createdSpecs.length > 0) {
    const tasks = await loadAllTasks(ctx);
    // Combine existing task slugs + all slugs reserved during this import (plan + specs)
    const importSlugs = new Set([
      ...tasks.flatMap((t) => t.slugs),
      ...importReservedSlugs,
    ]);

    // AC: @plan-import ac-35 - Build spec→task slug mapping for depends_on resolution
    // First pass: generate all task slugs so we can resolve spec depends_on → task depends_on
    const specToTaskSlug = new Map<string, string>();
    for (const specRef of result.createdSpecs) {
      const specSlug = specRef.slice(1);
      const spec = createdSpecsMap.get(specSlug);
      if (!spec) continue;

      const taskTitle = `Implement ${spec.title}`;
      const taskSlug = generateSlug(taskTitle);

      let uniqueSlug = taskSlug;
      let counter = 1;
      while (importSlugs.has(uniqueSlug) || !refIndex.isSlugAvailable(uniqueSlug)) {
        uniqueSlug = `${taskSlug}-${counter}`;
        counter++;
      }
      importSlugs.add(uniqueSlug);
      importReservedSlugs.add(uniqueSlug);
      specToTaskSlug.set(specSlug, uniqueSlug);
    }

    for (const specRef of result.createdSpecs) {
      // Get spec from createdSpecsMap (works in both dry-run and real mode)
      const specSlug = specRef.slice(1);
      const spec = createdSpecsMap.get(specSlug);
      if (!spec) continue;

      const uniqueSlug = specToTaskSlug.get(specSlug)!;

      if (options.dryRun) {
        info(`Would derive task: @${uniqueSlug} from ${specRef}`);
        result.createdTasks.push(`@${uniqueSlug}`);
      } else {
        // AC: @plan-import ac-35 - Resolve spec depends_on to task depends_on
        const planSpec = parsed.specs.find(s =>
          (s.slug || generateSlug(s.title)) === specSlug
        );
        const taskDependsOn: string[] = [];
        if (planSpec?.depends_on) {
          for (const depRef of planSpec.depends_on) {
            const depSlug = depRef.startsWith("@") ? depRef.slice(1) : depRef;
            const depTaskSlug = specToTaskSlug.get(depSlug);
            if (depTaskSlug) {
              // Dependency spec was in this import — link to its derived task
              taskDependsOn.push(`@${depTaskSlug}`);
            } else {
              // Dependency spec already existed — find an existing task with that spec_ref
              const normalizedDepRef = normalizeRefInput(depRef);
              const existingTask = tasks.find(t => t.spec_ref === normalizedDepRef);
              if (existingTask && existingTask.slugs.length > 0) {
                taskDependsOn.push(`@${existingTask.slugs[0]}`);
              } else {
                // No task found for this spec — pass the spec ref as-is
                taskDependsOn.push(normalizedDepRef);
              }
            }
          }
        }

        // AC: @plan-import ac-19 - Task has both spec_ref and plan_ref
        const taskInput: TaskInput = {
          title: `Implement ${spec.title}`,
          type: "task",
          spec_ref: specRef,
          plan_ref: planRef,
          priority: 3,
          slugs: [uniqueSlug],
          tags: [],
          depends_on: taskDependsOn,
          notes: [],
        };

        const newTask = createTask(taskInput);

        // AC: @plan-import ac-13 - Scoped implementation notes
        if (planSpec?.implementation_notes) {
          // Per-spec notes go directly to this task
          newTask.notes.push({
            _ulid: ulid(),
            created_at: new Date().toISOString(),
            author,
            content: `Implementation notes:\n\n${planSpec.implementation_notes}`,
          });
        } else if (parsed.implementationNotes) {
          // No per-spec notes — reference the plan
          newTask.notes.push({
            _ulid: ulid(),
            created_at: new Date().toISOString(),
            author,
            content: `See plan ${planRef} for implementation notes`,
          });
        }

        await saveTask(ctx, newTask);
        result.createdTasks.push(`@${uniqueSlug}`);
        newPlan.derived_tasks.push(`@${uniqueSlug}`);

        info(`Derived task: @${uniqueSlug}`);
      }
    }
  }

  // Create manual tasks
  // AC: @plan-import ac-27
  if (parsed.tasks.additional_tasks) {
    // Reload tasks to catch any created by derive loop above
    // Combine with all slugs reserved during this import (plan + specs)
    const manualTasks = await loadAllTasks(ctx);
    const manualImportSlugs = new Set([
      ...manualTasks.flatMap((t) => t.slugs),
      ...importReservedSlugs,
    ]);

    for (const taskDef of parsed.tasks.additional_tasks) {
      const taskSlug = taskDef.slug || generateSlug(taskDef.title);

      // Ensure slug uniqueness across all namespaces + this import's slugs
      let uniqueSlug = taskSlug;
      let counter = 1;
      while (manualImportSlugs.has(uniqueSlug) || !refIndex.isSlugAvailable(uniqueSlug)) {
        uniqueSlug = `${taskSlug}-${counter}`;
        counter++;
      }
      manualImportSlugs.add(uniqueSlug);

      if (options.dryRun) {
        info(`Would create manual task: @${uniqueSlug}`);
        result.createdTasks.push(`@${uniqueSlug}`);
      } else {
        // AC: @plan-import ac-27, ac-35 - Manual tasks have plan_ref; spec_ref and depends_on honored
        const taskInput: TaskInput = {
          title: taskDef.title,
          type: "task",
          plan_ref: planRef,
          priority: taskDef.priority || 3,
          slugs: [uniqueSlug],
          tags: taskDef.tags || [],
          depends_on: (taskDef.depends_on || []).map(normalizeRefInput),
          notes: [],
          ...(taskDef.spec_ref ? { spec_ref: normalizeRefInput(taskDef.spec_ref) } : {}),
        };

        if (taskDef.description) {
          taskInput.notes = [
            {
              _ulid: ulid(),
              created_at: new Date().toISOString(),
              author,
              content: taskDef.description,
            },
          ];
        }

        const newTask = createTask(taskInput);
        await saveTask(ctx, newTask);
        result.createdTasks.push(`@${uniqueSlug}`);
        newPlan.derived_tasks.push(`@${uniqueSlug}`);

        info(`Created manual task: @${uniqueSlug}`);
      }
    }
  }

  // Save plan record
  // AC: @plan-import ac-24
  if (!options.dryRun) {
    await savePlan(ctx, newPlan);
    await commitIfShadow(ctx.shadow, "plan-import", planSlug, parsed.title);
  }

  // AC: @plan-import ac-23, ac-29 - Summary output
  const successCount =
    result.createdSpecs.length +
    result.updatedSpecs.length +
    result.createdTasks.length;
  const errorCount = result.errors.length + result.skipped.length;

  // AC: @plan-import ac-32 - JSON output
  if (isJsonMode()) {
    output({
      plan: planRef,
      created_specs: result.createdSpecs,
      updated_specs: result.updatedSpecs,
      created_tasks: result.createdTasks,
      errors: result.errors,
      skipped: result.skipped,
    });
  } else {
    // Human-readable output
    if (options.dryRun) {
      console.log("\nDry run - no changes made\n");
    }

    console.log(`Plan: ${planRef}`);
    console.log(`Created ${result.createdSpecs.length} specs`);
    if (result.updatedSpecs.length > 0) {
      console.log(`Updated ${result.updatedSpecs.length} specs`);
    }
    console.log(`Created ${result.createdTasks.length} tasks`);

    if (result.errors.length > 0) {
      console.log(`\nErrors (${result.errors.length}):`);
      for (const err of result.errors) {
        console.log(`  - ${err.message}`);
      }
    }

    if (result.skipped.length > 0) {
      console.log(`\nSkipped (${result.skipped.length}):`);
      for (const skip of result.skipped) {
        console.log(`  - @${skip.slug}: ${skip.reason}`);
      }
    }

    // AC: @plan-import ac-15, ac-23 - Exit code 0 on success
    if (!options.dryRun && successCount > 0) {
      success(
        `\nImported plan: ${successCount} items created, ${errorCount} errors`,
      );
    }
  }  // end of else block (non-JSON output)

  // Exit code logic
  // AC: @plan-import ac-15 - Dry run exits 0
  // AC: @plan-import ac-23 - Success with some errors still exits 0
  process.exit(EXIT_CODES.SUCCESS);
}

/**
 * Generate URL-safe slug from title
 */
function generateSlug(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 50);
}

update.rawOutput:
  1→/**
  2→ * Plan import CLI command
  3→ * AC: @plan-import ac-11 through ac-33
  4→ */
  5→
  6→import * as fs from "node:fs/promises";
  7→import * as path from "node:path";
  8→import type { Command } from "commander";
  9→import { markMutating } from "../command-annotations.js";
 10→import {
 11→  addChildItem,
 12→  buildIndexes,
 13→  createPlan,
 14→  createSpecItem,
 15→  createTask,
 16→  getAuthor,
 17→  initContext,
 18→  loadAllTasks,
 19→  loadPlans,
 20→  savePlan,
 21→  saveTask,
 22→  updateSpecItem,
 23→  type LoadedSpecItem,
 24→} from "../../parser/index.js";
 25→import {
 26→  parsePlanDocument,
 27→  topologicalSort,
 28→  validateParentRefs,
 29→  type PlanSpec,
 30→} from "../../parser/plan-document.js";
 31→import { commitIfShadow } from "../../parser/shadow.js";
 32→import { normalizeRefInput } from "../../schema/index.js";
 33→import type { PlanInput, SpecItemInput, TaskInput } from "../../schema/index.js";
 34→import { errors } from "../../strings/index.js";
 35→import { EXIT_CODES } from "../exit-codes.js";
 36→import { error, info, isJsonMode, output, success, warn } from "../output.js";
 37→import { ulid } from "ulid";
 38→
 39→/**
 40→ * Register plan import command
 41→ * AC: @plan-import ac-11, ac-15, ac-32
 42→ */
 43→export function registerPlanImportCommand(planCommand: Command): void {
 44→  markMutating(planCommand.command("import <path>"))
 45→    .description("Import plan document and auto-generate specs/tasks")
 46→    .requiredOption(
 47→      "--module <ref>",
 48→      "Module to add specs under (e.g., @core-module)",
 49→    )
 50→    .option("--dry-run", "Show what would be created without making changes")
 51→    .option("--update", "Update existing specs instead of skipping them")
 52→    .option("--json", "Output as JSON")
 53→    .addHelpText(
 54→      "after",
 55→      `
 56→Format:
 57→  Plan documents use markdown with a ## Specs section containing a fenced
 58→  YAML code block. The YAML must be wrapped in triple-backtick yaml markers:
 59→
 60→    ## Specs
 61→    \`\`\`yaml
 62→    - title: My Feature
 63→      type: feature
 64→    \`\`\`
 65→
 66→  Without the fenced code block, specs will not be detected.
 67→
 68→Examples:
 69→  $ kspec plan import ./plan.md --module @core
 70→  $ kspec plan import ./plan.md --module @api --dry-run
 71→  $ kspec plan import ./plan.md --module @features --update --json`,
 72→    )
 73→    .action(async (planPath: string, options) => {
 74→      try {
 75→        await importPlan(planPath, options);
 76→      } catch (err) {
 77→        error("Failed to import plan", err);
 78→        process.exit(EXIT_CODES.ERROR);
 79→      }
 80→    });
 81→}
 82→
 83→/**
 84→ * Import operation result
 85→ */
 86→interface ImportResult {
 87→  createdSpecs: string[];
 88→  updatedSpecs: string[];
 89→  createdTasks: string[];
 90→  errors: Array<{ message: string; spec?: PlanSpec }>;
 91→  skipped: Array<{ slug: string; reason: string }>;
 92→  planRef: string;
 93→}
 94→
 95→/**
 96→ * Import plan document and create specs/tasks
 97→ * AC: @plan-import ac-11 through ac-33
 98→ */
 99→async function importPlan(
100→  planPath: string,
101→  options: { module: string; dryRun?: boolean; update?: boolean },
102→): Promise<void> {
103→  // JSON mode is set by global preAction hook
104→
105→  const ctx = await initContext();
106→  const author = getAuthor(ctx.config?.identity?.author);
107→
108→  // Read plan file
109→  // AC: @plan-import ac-21 - Handle file read errors
110→  const fullPath = path.resolve(process.cwd(), planPath);
111→  let content: string;
112→  try {
113→    content = await fs.readFile(fullPath, "utf-8");
114→  } catch (err) {
115→    error(`Failed to read plan file: ${planPath}`, err);
116→    process.exit(EXIT_CODES.USAGE_ERROR);
117→  }
118→
119→  // Parse plan document
120→  // AC: @plan-import ac-11, ac-12, ac-13, ac-21, ac-22
121→  const parsed = parsePlanDocument(content);
122→
123→  // Report parsing errors
124→  if (parsed.errors.length > 0) {
125→    for (const err of parsed.errors) {
126→      if (err.type === "yaml") {
127→        // AC: @plan-import ac-21 - YAML parse errors (fatal)
128→        error(err.message);
129→        process.exit(EXIT_CODES.USAGE_ERROR);
130→      } else if (err.type === "validation") {
131→        // AC: @plan-import ac-22 - Validation errors (non-fatal, add to warnings)
132→        warn(err.message);
133→      }
134→    }
135→  }
136→
137→  // Load plans for cross-namespace slug safety
138→  const plans = await loadPlans(ctx);
139→
140→  // Build indexes to check existing specs (include plans for cross-namespace slug safety)
141→  const { refIndex, items } = await buildIndexes(ctx, plans);
142→  const existingSpecRefs = new Set<string>();
143→  for (const item of items) {
144→    for (const slug of (item as LoadedSpecItem).slugs || []) {
145→      existingSpecRefs.add(slug);
146→    }
147→    existingSpecRefs.add(item._ulid.slice(0, 8));
148→  }
149→
150→  // Resolve module reference
151→  const moduleResult = refIndex.resolve(options.module);
152→  if (!moduleResult.ok) {
153→    error(errors.reference.itemNotFound(options.module));
154→    process.exit(EXIT_CODES.NOT_FOUND);
155→  }
156→
157→  const moduleItem = moduleResult.item as LoadedSpecItem;
158→
159→  // Verify it's a module
160→  if (moduleItem.type !== "module") {
161→    error(`${options.module} is not a module (type: ${moduleItem.type})`);
162→    process.exit(EXIT_CODES.USAGE_ERROR);
163→  }
164→
165→  // Validate parent references
166→  // AC: @plan-import ac-17, ac-33
167→  const parentErrors = validateParentRefs(parsed.specs, existingSpecRefs);
168→  parsed.errors.push(...parentErrors);
169→
170→  // Sort specs topologically
171→  // AC: @plan-import ac-16, ac-18
172→  const { sorted, error: sortError } = topologicalSort(parsed.specs);
173→  if (sortError) {
174→    // AC: @plan-import ac-18 - Circular dependency detection
175→    error(sortError.message);
176→    process.exit(EXIT_CODES.USAGE_ERROR);
177→  }
178→
179→  // Create plan record
180→  // AC: @plan-import ac-24, ac-28
181→  // Auto-namespace plan slugs with "plan-" prefix to prevent collision with spec slugs
182→  // Ensure uniqueness across all namespaces (plans + specs + tasks via refIndex)
183→  let planSlug = `plan-${generateSlug(parsed.title)}`;
184→  let counter = 1;
185→  const baseSlug = planSlug;
186→  while (!refIndex.isSlugAvailable(planSlug)) {
187→    planSlug = `${baseSlug}-${counter}`;
188→    counter++;
189→  }
190→
191→  // Track all slugs created during this import (refIndex is stale after mutations)
192→  const importReservedSlugs = new Set<string>([planSlug]);
193→
194→  const planInput: PlanInput = {
195→    title: parsed.title,
196→    content: parsed.content,
197→    status: "active",
198→    slugs: [planSlug],
199→    source_path: fullPath,
200→  };
201→
202→  const newPlan = createPlan(planInput);
203→  const planRef = `@${planSlug}`;
204→
205→  // AC: @plan-import ac-13 - Attach global implementation notes to plan record
206→  if (parsed.implementationNotes) {
207→    newPlan.notes.push({
208→      _ulid: ulid(),
209→      created_at: new Date().toISOString(),
210→      author,
211→      content: `Implementation notes:\n\n${parsed.implementationNotes}`,
212→    });
213→  }
214→
215→  // Initialize result
216→  const result: ImportResult = {
217→    createdSpecs: [],
218→    updatedSpecs: [],
219→    createdTasks: [],
220→    errors: [],
221→    skipped: [],
222→    planRef,
223→  };
224→
225→  // Add parser validation errors to result
226→  // AC: @plan-import ac-22, ac-29 - Include parser validation errors in summary
227→  for (const err of parsed.errors) {
228→    if (err.type === "validation") {
229→      result.errors.push({ message: err.message });
230→    }
231→  }
232→
233→  // Track newly created specs for parent resolution
234→  // AC: @plan-import ac-16 - Resolve local references
235→  const createdSpecsMap = new Map<string, LoadedSpecItem>();
236→
237→  // Process specs
238→  // AC: @plan-import ac-14, ac-16, ac-17, ac-22, ac-23, ac-25, ac-26, ac-29
239→  for (let i = 0; i < sorted.length; i++) {
240→    const spec = sorted[i];
241→    try {
242→      // Validate required fields first
243→      // AC: @plan-import ac-22
244→      if (!spec.title) {
245→        const errMsg = `Spec at index ${i} missing required field: title`;
246→        warn(errMsg);
247→        result.errors.push({ message: errMsg, spec });
248→        continue;
249→      }
250→
251→      const specSlug = spec.slug || generateSlug(spec.title);
252→      const specRef = `@${specSlug}`;
253→
254→      // Check against slugs reserved during this import (plan slug, earlier specs)
255→      if (importReservedSlugs.has(specSlug)) {
256→        warn(`Spec slug "${specSlug}" collides with another item in this import, skipping`);
257→        result.skipped.push({ slug: specSlug, reason: "Slug collision within import" });
258→        continue;
259→      }
260→
261→      // Check if spec already exists in pre-import state
262→      const exists = refIndex.resolve(specRef);
263→
264→      if (exists.ok && !options.update) {
265→        // AC: @plan-import ac-14, ac-25 - Skip existing specs
266→        warn(`Skipping existing spec: ${specRef}`);
267→        result.skipped.push({ slug: specSlug, reason: "Already exists" });
268→        continue;
269→      }
270→
271→      if (exists.ok && options.update) {
272→        // AC: @plan-import ac-26 - Update existing spec
273→        // Updates: description, type, tags, traits, and acceptance_criteria
274→        const existingSpec = exists.item as LoadedSpecItem;
275→
276→        if (options.dryRun) {
277→          info(`Would update spec: ${specRef}`);
278→          result.updatedSpecs.push(specRef);
279→        } else {
280→          // Build updates from plan spec
281→          const updates: Partial<SpecItemInput> = {};
282→
283→          if (spec.description !== undefined) {
284→            updates.description = spec.description;
285→          }
286→          if (spec.type !== undefined) {
287→            updates.type = spec.type as SpecItemInput["type"];
288→          }
289→          if (spec.traits !== undefined) {
290→            updates.traits = spec.traits.map(normalizeRefInput);
291→          }
292→          if (spec.depends_on !== undefined) {
293→            updates.depends_on = spec.depends_on.map(normalizeRefInput);
294→          }
295→          if (spec.acceptance_criteria !== undefined) {
296→            updates.acceptance_criteria = spec.acceptance_criteria;
297→          }
298→
299→          await updateSpecItem(ctx, existingSpec, updates);
300→          info(`Updated spec: ${specRef}`);
301→          result.updatedSpecs.push(specRef);
302→        }
303→        continue;
304→      }
305→
306→      // Resolve parent reference
307→      // AC: @plan-import ac-16, ac-17
308→      let parent: LoadedSpecItem | null = null;
309→      if (spec.parent) {
310→        const parentRef = normalizeRefInput(spec.parent);
311→
312→        // Check if parent was just created in this import
313→        const parentSlug = parentRef.slice(1);
314→        if (createdSpecsMap.has(parentSlug)) {
315→          parent = createdSpecsMap.get(parentSlug)!;
316→        } else {
317→          // Check existing specs
318→          const parentResult = refIndex.resolve(parentRef);
319→
320→          if (!parentResult.ok) {
321→            // AC: @plan-import ac-17, ac-33 - Missing parent with hint
322→            const errMsg = `Parent ${parentRef} not found. Check parent exists or define it earlier in plan`;
323→            warn(errMsg);
324→            result.errors.push({ message: errMsg, spec });
325→            result.skipped.push({ slug: specSlug, reason: "Missing parent" });
326→            continue;
327→          }
328→
329→          parent = parentResult.item as LoadedSpecItem;
330→        }
331→      }
332→
333→      // Determine if this is a root-level trait (type: trait with no parent)
334→      const isRootTrait = (spec.type === "trait") && !parent;
335→
336→      if (options.dryRun) {
337→        // AC: @plan-import ac-15 - Dry run mode
338→        info(
339→          `Would create spec: ${specRef} ${spec.parent ? `under ${spec.parent}` : isRootTrait ? "(project-level trait)" : "(root)"}`,
340→        );
341→        result.createdSpecs.push(specRef);
342→        importReservedSlugs.add(specSlug);
343→
