          info("No changes specified");
          return;
        }

        await savePlan(ctx, foundPlan);
        await commitIfShadow(
          ctx.shadow,
          "plan-set",
          foundPlan.slugs[0] || foundPlan._ulid.slice(0, 8),
          changes.join(", "),
