274→/**
275→ * Sort specs in topological order (parents before children).
276→ *
277→ * AC: @plan-import ac-16 - Create specs in dependency order
278→ * AC: @plan-import ac-18 - Detect circular dependencies
279→ *
280→ * @returns Sorted specs or null if circular dependency detected
281→ */
282→export function topologicalSort(
283→  specs: PlanSpec[],
284→): { sorted: PlanSpec[]; error: ParseError | null } {
285→  // Build adjacency list
286→  const graph = new Map<string, string[]>();
287→  const specBySlug = new Map<string, PlanSpec>();
288→
289→  for (const spec of specs) {
290→    const slug = spec.slug || slugify(spec.title);
291→    if (specBySlug.has(slug)) {
292→      return {
293→        sorted: [],
294→        error: {
295→          type: "validation",
296→          message: `Duplicate slug detected: "${slug}". Ensure each spec has a unique slug or title.`,
297→        },
298→      };
299→    }
300→    specBySlug.set(slug, spec);
301→    graph.set(slug, []);
302→  }
303→
304→  // Add edges for parent dependencies
305→  for (const spec of specs) {
306→    const slug = spec.slug || slugify(spec.title);
307→    if (spec.parent) {
308→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
309→
310→      // Only add edge if parent is in this plan (local reference)
311→      if (specBySlug.has(parentRef)) {
312→        const children = graph.get(parentRef) || [];
313→        children.push(slug);
314→        graph.set(parentRef, children);
315→      }
316→    }
317→  }
318→
319→  // Detect cycles using DFS
320→  const visited = new Set<string>();
321→  const recursionStack = new Set<string>();
322→
323→  function hasCycle(node: string, path: string[]): string[] | null {
324→    visited.add(node);
325→    recursionStack.add(node);
326→
327→    const children = graph.get(node) || [];
328→    for (const child of children) {
329→      if (!visited.has(child)) {
330→        const cyclePath = hasCycle(child, [...path, child]);
331→        if (cyclePath) return cyclePath;
332→      } else if (recursionStack.has(child)) {
333→        return [...path, child];
334→      }
335→    }
336→
337→    recursionStack.delete(node);
338→    return null;
339→  }
340→
341→  for (const slug of graph.keys()) {
342→    if (!visited.has(slug)) {
343→      const cyclePath = hasCycle(slug, [slug]);
344→      if (cyclePath) {
345→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
346→        return {
347→          sorted: [],
348→          error: {
349→            type: "circular",
350→            message: `Circular parent reference: ${cycleRefs}`,
351→          },
352→        };
353→      }
354→    }
355→  }
356→
357→  // Topological sort using DFS
358→  const sorted: PlanSpec[] = [];
359→  const processed = new Set<string>();
360→
361→  function visit(node: string) {
362→    if (processed.has(node)) return;
363→
364→    const spec = specBySlug.get(node);
365→    if (!spec) return;
366→
367→    // Visit parent first if it's in this plan
368→    if (spec.parent) {
369→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
370→      if (specBySlug.has(parentRef)) {
371→        visit(parentRef);
372→      }
373→    }
374→
375→    processed.add(node);
376→    sorted.push(spec);
377→  }
378→
379→  for (const slug of specBySlug.keys()) {
380→    visit(slug);
381→  }
382→
383→  return { sorted, error: null };
384→}
385→
386→/**
387→ * Simple slugification helper
388→ */
389→function slugify(title: string): string {
390→  return title
391→    .toLowerCase()
392→    .replace(/[^a-z0-9]+/g, "-")
393→    .replace(/^-|-$/g, "");
394→}
395→
396→/**
397→ * Validate parent references.
398→ *
399→ * AC: @plan-import ac-17 - Detect missing parent references
400→ * AC: @plan-import ac-33 - Provide recovery hints
401→ *
402→ * @param specs Specs to validate
403→ * @param existingRefs Set of existing spec refs in the project
404→ * @returns Errors for specs with invalid parents
405→ */
406→export function validateParentRefs(
407→  specs: PlanSpec[],
408→  existingRefs: Set<string>,
409→): ParseError[] {
410→  const errors: ParseError[] = [];
411→  const planSlugs = new Set(
412→    specs.map(s => s.slug || slugify(s.title))
413→  );
414→
415→  for (const spec of specs) {
416→    if (!spec.parent) continue;
417→
418→    const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
419→
420→    // Check if parent exists in plan or project
421→    if (!planSlugs.has(parentRef) && !existingRefs.has(parentRef)) {
422→      errors.push({
423→        type: "dependency",
424→        message: `Parent ${spec.parent} not found. Check parent exists or define it earlier in plan`,
425→        spec,
426→      });
427→    }
428→  }
429→
430→  return errors;
431→}
