185→/**
186→ * Save a single plan (create or update)
187→ * AC: @plan-crud ac-1, ac-3 - save plan changes
188→ * Uses file lock to prevent TOCTOU race on concurrent writes.
189→ */
190→export async function savePlan(
191→  ctx: KspecContext,
192→  plan: LoadedPlan,
193→): Promise<void> {
194→  const plansPath = getPlansFilePath(ctx);
195→  const lockPath = `${plansPath}.lock`;
196→
197→  // Ensure directory exists
198→  const dir = path.dirname(plansPath);
199→  await fs.mkdir(dir, { recursive: true });
200→
201→  // Acquire lock for atomic read-modify-write
202→  const releaseLock = await acquireLock(lockPath);
203→  try {
204→    // Load existing plans (inside lock to prevent TOCTOU)
205→    const plans = await loadPlans(ctx);
206→
207→    // Strip runtime metadata before saving
208→    const { _sourceFile, ...cleanPlan } = plan;
209→
210→    // Update or add
211→    const existingIndex = plans.findIndex((p) => p._ulid === plan._ulid);
212→    if (existingIndex >= 0) {
213→      plans[existingIndex] = cleanPlan as Plan;
214→    } else {
215→      plans.push(cleanPlan as Plan);
216→    }
217→
218→    // Save back to file
219→    const plansFile: PlansFile = {
220→      kynetic_plans: "1.0",
221→      plans: plans.map(({ _sourceFile, ...p }) => p as Plan),
222→    };
223→
224→    await writeYamlFilePreserveFormat(plansPath, plansFile);
225→  } finally {
226→    await releaseLock();
227→  }
228→}
229→
230→/**
231→ * Delete a plan by ULID
232→ */
233→export async function deletePlan(
234→  ctx: KspecContext,
235→  planUlid: string,
236→): Promise<boolean> {
237→  const plansPath = getPlansFilePath(ctx);
238→
239→  try {
240→    const plans = await loadPlans(ctx);
241→
242→    // Find plan to delete
243→    const index = plans.findIndex((p) => p._ulid === planUlid);
244→    if (index < 0) {
245→      return false;
246→    }
247→
248→    // Remove plan
249→    plans.splice(index, 1);
250→
251→    // Save back
252→    const plansFile: PlansFile = {
253→      kynetic_plans: "1.0",
254→      plans: plans.map(({ _sourceFile, ...p }) => p as Plan),
255→    };
256→
257→    await writeYamlFilePreserveFormat(plansPath, plansFile);
258→    return true;
259→  } catch {
260→    return false;
261→  }
262→}
263→
264→/**
265→ * Filter plans by status
266→ * AC: @plan-crud ac-7 - list with status filter
267→ */
268→export function filterPlansByStatus(
269→  plans: LoadedPlan[],
270→  status?: string,
271→): LoadedPlan[] {
272→  if (!status) return plans;
273→  return plans.filter((p) => p.status === status);
274→}
275→
276→/**
277→ * Get plan statistics
278→ */
279→export function getPlanStats(plans: LoadedPlan[]): {
280→  total: number;
281→  byStatus: Record<string, number>;
282→} {
