299→      };
300→    }
301→    specBySlug.set(slug, spec);
302→    graph.set(slug, []);
303→  }
304→
305→  // Add edges for parent dependencies
306→  for (const spec of specs) {
307→    const slug = spec.slug || slugify(spec.title);
308→    if (spec.parent) {
309→      const parentRef = spec.parent.startsWith("@") ? spec.parent.slice(1) : spec.parent;
310→
311→      // Only add edge if parent is in this plan (local reference)
312→      if (specBySlug.has(parentRef)) {
313→        const children = graph.get(parentRef) || [];
314→        children.push(slug);
315→        graph.set(parentRef, children);
316→      }
317→    }
318→  }
