320→  // Detect cycles using DFS
321→  const visited = new Set<string>();
322→  const recursionStack = new Set<string>();
323→
324→  function hasCycle(node: string, path: string[]): string[] | null {
325→    visited.add(node);
326→    recursionStack.add(node);
327→
328→    const children = graph.get(node) || [];
329→    for (const child of children) {
330→      if (!visited.has(child)) {
331→        const cyclePath = hasCycle(child, [...path, child]);
332→        if (cyclePath) return cyclePath;
333→      } else if (recursionStack.has(child)) {
