335→      }
336→    }
337→
338→    recursionStack.delete(node);
339→    return null;
340→  }
341→
342→  for (const slug of graph.keys()) {
343→    if (!visited.has(slug)) {
344→      const cyclePath = hasCycle(slug, [slug]);
345→      if (cyclePath) {
346→        const cycleRefs = cyclePath.map(s => `@${s}`).join(" -> ");
347→        return {
348→          sorted: [],
349→          error: {
350→            type: "circular",
351→            message: `Circular parent reference: ${cycleRefs}`,
352→          },
353→        };
354→      }
355→    }
356→  }
357→
358→  // Topological sort using DFS
359→  const sorted: PlanSpec[] = [];
360→  const processed = new Set<string>();
361→
362→  function visit(node: string) {
363→    if (processed.has(node)) return;
364→
365→    const spec = specBySlug.get(node);
366→    if (!spec) return;
367→
368→    // Visit parent first if it's in this plan
