  1566→                          readEndLoopMarker(ctx.rootDir)
  1567→                            .then((marker) => {
  1568→                              const reason = marker?.reason
  1569→                                ? ` (${marker.reason})`
  1570→                                : "";
  1571→                              info(`End-loop signal received${reason}`);
