  1575→                            });
  1576→                        }
  1577→                      }
  1578→
  1579→                      // Log raw update event (async, non-blocking)
  1580→                      // Look up iteration by ACP session ID so late updates from
  1581→                      // a previous session are attributed to the correct iteration
  1582→                      const eventIteration = sessionIterationMap.get(_sid) ?? 0;
  1583→                      appendEvent(specDir, {
