   100→ * AC: @batch-exec ac-json-mode-field — JSON output includes mode field
   101→ */
   102→export function registerBatchCommand(program: Command): void {
   103→  const batchCmd = program
   104→    .command("batch")
   105→    .description("Execute multiple commands from a JSON payload")
   106→    .option("--file <path>", "Read commands from a JSON file")
   107→    .option("--commands <json>", "Inline JSON command array")
   108→    .option("--no-atomic", "Immediate mode: per-command commits, no rollback")
   109→    .option("--continue", "Continue on error (implies --no-atomic)")
   110→    .option("--dry-run", "Validate without executing")
   111→    .addHelpText(
   112→      "after",
