   116→  $ kspec batch --file commands.json
   117→  $ kspec batch --commands '[{"command":"inbox add","args":{"content":"test"}}]'
   118→  $ kspec batch --no-atomic --commands '[...]'
   119→  $ kspec batch --continue --commands '[...]'
   120→  $ kspec batch --dry-run --commands '[...]'
   121→  $ kspec batch commands           # list allowed commands`,
   122→    )
