   154→      // Parse input
   155→      let commands;
   156→      try {
   157→        commands = await parseBatchInput(source);
   158→      } catch (err) {
   159→        if (err instanceof BatchParseError) {
   160→          if (json) {
   161→            console.log(JSON.stringify({
   162→              success: false,
   163→              error: err.message,
   164→            }, null, 2));
   165→          } else {
