   193→            `Batch failed (${modeLabel}): ${result.summary.succeeded}/${result.summary.total} succeeded, ${result.summary.failed} failed`,
   194→          );
   195→        }
   196→
   197→        // Show per-command results
   198→        for (const r of result.results) {
   199→          const label = r.id ?? `#${r.index}`;
   200→          if (r.success) {
   201→            console.log(`  [${label}] ${r.command}: OK`);
   202→          } else {
   203→            let errorLine = `  [${label}] ${r.command}: FAILED — ${r.error}`;
   204→            if (r.suggestion) {
   205→              errorLine += ` Did you mean: ${r.suggestion}?`;
   206→            }
   207→            console.error(errorLine);
   208→          }
   209→        }
   210→
   211→        // Show helpful hint only for validation failures (not runtime execution failures)
   212→        if (result.validationFailed) {
