    42→/**
    43→ * Options for executeBatchOperation
    44→ */
    45→export interface BatchOperationOptions<TItem, TContext> {
    46→  /** The positional ref argument (if provided) */
    47→  positionalRef?: string;
    48→  /** The --refs flag values (if provided) */
    49→  refsFlag?: string[];
    50→  /** Context needed for operations */
    51→  context: TContext;
    52→  /** All items to search through */
    53→  items: TItem[];
    54→  /** Reference index for resolution */
    55→  index: ReferenceIndex;
    56→  /** Function to resolve a ref to an item - returns { item, error? } */
    57→  resolveRef: (
    58→    ref: string,
    59→    items: TItem[],
    60→    index: ReferenceIndex,
    61→  ) => { item: TItem | null; error?: string };
    62→  /** Function to execute the operation on a single item */
    63→  executeOperation: (
    64→    item: TItem,
    65→    context: TContext,
    66→  ) => Promise<{
    67→    success: boolean;
    68→    message?: string;
    69→    error?: string;
    70→    warning?: string;
    71→    data?: unknown;
    72→  }>;
    73→  /** Function to extract ULID from an item */
    74→  getUlid: (item: TItem) => string;
    75→}
    76→
    77→/**
    78→ * Execute a batch operation with support for single-ref (positional) or multi-ref (--refs flag).
    79→ * Handles mutual exclusion, partial failures, and unified output formatting.
    80→ *
    81→ * Returns a BatchResult object. Caller should use formatBatchOutput() to render results.
    82→ */
    83→export async function executeBatchOperation<TItem, TContext>(
    84→  options: BatchOperationOptions<TItem, TContext>,
    85→): Promise<BatchResult> {
    86→  const {
    87→    positionalRef,
    88→    refsFlag,
    89→    context,
    90→    items,
    91→    index,
    92→    resolveRef,
    93→    executeOperation,
    94→    getUlid,
    95→  } = options;
    96→
    97→  // AC: @multi-ref-batch ac-3 - Mutual exclusion check
    98→  if (positionalRef && refsFlag && refsFlag.length > 0) {
    99→    error("Cannot use both positional ref and --refs flag");
   100→    process.exit(EXIT_CODES.USAGE_ERROR);
   101→  }
   102→
   103→  // Determine which refs to process
   104→  let refs: string[];
   105→  if (refsFlag && refsFlag.length > 0) {
   106→    refs = refsFlag;
   107→  } else if (positionalRef) {
   108→    refs = [positionalRef];
   109→  } else {
   110→    // AC: @multi-ref-batch ac-7 - Empty refs error
   111→    error("--refs requires at least one reference");
   112→    process.exit(EXIT_CODES.USAGE_ERROR);
   113→  }
   114→
   115→  // Process each ref
   116→  const results: BatchOperationResult[] = [];
   117→
   118→  // AC: @multi-ref-batch ac-4 - Continue processing after errors (partial failure handling)
   119→  for (const ref of refs) {
   120→    try {
   121→      // AC: @multi-ref-batch ac-8 - Ref resolution uses existing logic
   122→      const resolved = resolveRef(ref, items, index);
   123→
   124→      if (!resolved.item) {
   125→        // Resolution failed - record error and continue to next ref
   126→        results.push({
   127→          ref,
   128→          ulid: null,
   129→          status: "error",
   130→          error: resolved.error || `Failed to resolve reference: ${ref}`,
   131→        });
   132→        continue;
   133→      }
   134→
   135→      const ulid = getUlid(resolved.item);
   136→
   137→      // Execute the operation
   138→      const opResult = await executeOperation(resolved.item, context);
   139→
   140→      results.push({
   141→        ref,
   142→        ulid: index.shortUlid(ulid),
   143→        status: opResult.success ? "success" : "error",
   144→        message: opResult.message,
   145→        error: opResult.error,
   146→        warning: opResult.warning,
   147→        data: opResult.data,
   148→      });
   149→    } catch (err) {
   150→      // Unexpected error during operation
   151→      results.push({
   152→        ref,
   153→        ulid: null,
   154→        status: "error",
   155→        error: err instanceof Error ? err.message : String(err),
   156→      });
   157→    }
   158→  }
   159→
   160→  // Calculate summary
   161→  const succeeded = results.filter((r) => r.status === "success").length;
   162→  const failed = results.filter((r) => r.status === "error").length;
   163→  const summary: BatchSummary = {
   164→    total: results.length,
   165→    succeeded,
   166→    failed,
   167→  };
   168→
   169→  // Determine overall success
   170→  const success = failed === 0;
   171→
   172→  return {
   173→    success,
   174→    summary,
   175→    results,
   176→  };
   177→}
   178→
   179→/**
   180→ * Format and output batch operation results.
   181→ * Handles both human-readable and JSON output formats.
   182→ * Sets appropriate exit code based on results.
   183→ *
   184→ * AC: @multi-ref-batch ac-5 - Human output format
   185→ * AC: @multi-ref-batch ac-6 - JSON output format
   186→ */
   187→export function formatBatchOutput(
   188→  result: BatchResult,
   189→  operationName: string,
   190→): void {
   191→  if (isJsonMode()) {
   192→    // AC: @multi-ref-batch ac-6 - JSON output
   193→    console.log(JSON.stringify(result, null, 2));
   194→  } else {
   195→    // AC: @multi-ref-batch ac-5 - Human output format
   196→    const { summary, results } = result;
   197→
   198→    // Summary line
   199→    if (summary.total === 1) {
   200→      // Single item - no summary needed, just show result
   201→      const r = results[0];
   202→      if (r.status === "success") {
   203→        console.log(chalk.green(`✓ ${operationName}: ${r.ulid || r.ref}`));
   204→        if (r.message) {
   205→          console.log(`  ${r.message}`);
   206→        }
   207→      } else {
   208→        console.log(chalk.red(`✗ ${operationName} failed: ${r.ref}`));
   209→        if (r.error) {
   210→          console.log(chalk.red(`  ${r.error}`));
   211→        }
   212→      }
   213→    } else {
   214→      // Multiple items - show summary
   215→      const _verb = operationName.toLowerCase();
   216→      console.log(
   217→        `${chalk.bold(
   218→          `${operationName}d ${summary.succeeded} of ${summary.total}:`,
   219→        )}\n`,
   220→      );
   221→
   222→      // List each result
   223→      for (const r of results) {
   224→        if (r.status === "success") {
   225→          console.log(chalk.green(`✓ ${r.ulid || r.ref}`));
   226→          if (r.message) {
   227→            console.log(`  ${r.message}`);
   228→          }
   229→        } else {
   230→          console.log(chalk.red(`✗ ${r.ref}`));
   231→          if (r.error) {
   232→            console.log(chalk.red(`  ${r.error}`));
   233→          }
   234→        }
   235→      }
   236→    }
   237→  }
   238→
   239→  // Set exit code
   240→  // AC: @multi-ref-batch ac-4 - Partial failure exit code
   241→  if (!result.success) {
   242→    if (result.summary.succeeded > 0) {
   243→      // Partial failure
   244→      process.exit(EXIT_CODES.ERROR);
   245→    } else {
   246→      // Complete failure
   247→      process.exit(EXIT_CODES.ERROR);
   248→    }
   249→  }
   250→}
   251→
   252→/**
   253→ * Helper to check if refs flag is being used (for backward compatibility checks)
   254→ */
   255→export function isBatchMode(refsFlag?: string[]): boolean {
   256→  return Boolean(refsFlag && refsFlag.length > 0);
   257→}
   258→
