  1384→
  1385→/**
  1386→ * Extract a content excerpt around a match, limited to maxLength chars.
  1387→ *
  1388→ * AC: @session-log-search ac-4
  1389→ */
  1390→function extractContentExcerpt(
  1391→  data: unknown,
  1392→  pattern: string,
  1393→  maxLength: number = 200,
  1394→): string {
  1395→  // Stringify the data for searching
  1396→  const str = JSON.stringify(data);
  1397→  const lowerStr = str.toLowerCase();
  1398→  const lowerPattern = pattern.toLowerCase();
  1399→
  1400→  const matchIndex = lowerStr.indexOf(lowerPattern);
  1401→  if (matchIndex === -1) {
  1402→    // Shouldn't happen since we pre-filtered, but return start of content
  1403→    return str.length > maxLength ? str.slice(0, maxLength - 3) + "..." : str;
  1404→  }
  1405→
  1406→  // Calculate excerpt window centered on match
  1407→  const matchLen = pattern.length;
  1408→  const contextBefore = Math.floor((maxLength - matchLen) / 2);
  1409→  const start = Math.max(0, matchIndex - contextBefore);
  1410→  const end = Math.min(str.length, start + maxLength);
  1411→
  1412→  let excerpt = str.slice(start, end);
  1413→
  1414→  // Add ellipsis indicators
  1415→  if (start > 0) {
  1416→    excerpt = "..." + excerpt.slice(3);
  1417→  }
  1418→  if (end < str.length) {
  1419→    excerpt = excerpt.slice(0, -3) + "...";
  1420→  }
  1421→
  1422→  return excerpt;
  1423→}
  1424→
  1425→/**
  1426→ * Search across session events for a pattern.
  1427→ *
  1428→ * This streams through events.jsonl files, applying filters as early as possible
  1429→ * for performance. Sessions are pre-filtered by metadata (--since, --agent) before
  1430→ * scanning events to reduce I/O.
  1431→ *
  1432→ * AC: @session-log-search ac-1, ac-2, ac-3, ac-5, ac-7
  1433→ *
  1434→ * @param specDir - The .kspec directory path
  1435→ * @param pattern - Case-insensitive substring to search for
  1436→ * @param options - Search filtering options
  1437→ * @returns Array of search results grouped by session
  1438→ */
  1439→export async function searchSessionEvents(
  1440→  specDir: string,
  1441→  pattern: string,
  1442→  options: SearchOptions = {},
  1443→): Promise<SessionSearchResult[]> {
  1444→  // Defense-in-depth: normalize limit to a valid positive integer
  1445→  const rawLimit = options.limit ?? 50;
  1446→  const limit = Number.isNaN(rawLimit) || rawLimit <= 0 ? 50 : rawLimit;
  1447→  const lowerPattern = pattern.toLowerCase();
  1448→
  1449→  // Get all session summaries for metadata filtering
  1450→  const allSummaries = await getAllSessionLogSummaries(specDir);
  1451→
  1452→  // AC: @session-log-search ac-3 - Pre-filter by --since
  1453→  let filteredSummaries = allSummaries;
  1454→  if (options.sinceDate) {
  1455→    filteredSummaries = filteredSummaries.filter(
  1456→      (s) => new Date(s.started_at) >= options.sinceDate!,
  1457→    );
  1458→  }
  1459→
  1460→  // AC: @session-log-search ac-7 - Pre-filter by --agent
  1461→  if (options.agentType) {
  1462→    filteredSummaries = filteredSummaries.filter(
  1463→      (s) => s.agent_type === options.agentType,
  1464→    );
  1465→  }
  1466→
  1467→  const results: SessionSearchResult[] = [];
  1468→  let totalMatches = 0;
  1469→
  1470→  for (const summary of filteredSummaries) {
  1471→    if (totalMatches >= limit) break;
  1472→
  1473→    const eventsPath = getSessionEventsPath(specDir, summary.id);
  1474→    let content: string;
  1475→    try {
  1476→      content = await fsPromises.readFile(eventsPath, "utf-8");
  1477→    } catch {
  1478→      continue; // Skip sessions without events
  1479→    }
  1480→
  1481→    if (!content.trim()) continue;
  1482→
  1483→    const matches: SearchMatch[] = [];
  1484→    const lines = content.trim().split("\n");
  1485→    // Track seen tool_call IDs to skip phased duplicates
  1486→    const seenToolCallIds = new Set<string>();
  1487→
  1488→    for (const line of lines) {
  1489→      if (totalMatches >= limit) break;
  1490→
  1491→      // Quick substring pre-filter before parsing JSON
  1492→      if (!line.toLowerCase().includes(lowerPattern)) continue;
  1493→
  1494→      try {
  1495→        const event = JSON.parse(line);
  1496→
  1497→        // AC: @session-log-search ac-2 - Filter by event type
  1498→        if (options.eventType && event.type !== options.eventType) continue;
  1499→
  1500→        // Deduplicate phased tool_call events
  1501→        if (event?.type === "session.update") {
  1502→          const update = event?.data?.update;
  1503→          if (update?.sessionUpdate === "tool_call") {
  1504→            const toolCallId = update?.toolCallId || update?.tool_call_id || update?.id;
  1505→            if (toolCallId) {
  1506→              if (seenToolCallIds.has(toolCallId)) continue;
  1507→              seenToolCallIds.add(toolCallId);
  1508→            }
  1509→          }
  1510→        }
  1511→
  1512→        // Verify match in stringified data (not just line, in case pattern appears in metadata)
  1513→        const dataStr = JSON.stringify(event.data);
  1514→        if (!dataStr.toLowerCase().includes(lowerPattern)) continue;
  1515→
  1516→        // AC: @session-log-search ac-4 - Create match with excerpt
  1517→        matches.push({
  1518→          session_id: summary.id,
  1519→          timestamp: event.ts,
  1520→          event_type: event.type,
  1521→          content_excerpt: extractContentExcerpt(event.data, pattern, 200),
  1522→        });
  1523→        totalMatches++;
  1524→      } catch {
  1525→        // Skip unparseable lines
  1526→      }
  1527→    }
  1528→
  1529→    if (matches.length > 0) {
  1530→      results.push({
  1531→        session_id: summary.id,
  1532→        agent_type: summary.agent_type,
  1533→        started_at: summary.started_at,
  1534→        matches,
  1535→      });
  1536→    }
  1537→  }
  1538→
  1539→  return results;
  1540→}
  1541→
  1542→// ─── Task Budget ──────────────────────────────────────────────────────────────
  1543→
  1544→/**
  1545→ * Atomic JSON write — write to temp file then rename in same directory.
  1546→ * Prevents corruption on crash.
  1547→ * AC: @task-budget-enforcement ac-atomic-write
  1548→ */
  1549→async function writeBudgetAtomic(
  1550→  filePath: string,
  1551→  budget: TaskBudget,
  1552→): Promise<void> {
  1553→  const dir = path.dirname(filePath);
  1554→  await fsPromises.mkdir(dir, { recursive: true });
  1555→  const tmpPath = `${filePath}.${process.pid}.tmp`;
  1556→  const content = JSON.stringify(budget, null, 2) + "\n";
  1557→  await fsPromises.writeFile(tmpPath, content, "utf-8");
  1558→  await fsPromises.rename(tmpPath, filePath);
  1559→}
  1560→
  1561→/**
  1562→ * Create a budget for a session.
  1563→ *
  1564→ * Writes budget.json to .kspec/sessions/{id}/ on the local filesystem
  1565→ * (NOT committed to shadow branch).
  1566→ *
  1567→ * AC: @session-creation-and-env-injection ac-budget
  1568→ * AC: @session-creation-and-env-injection ac-budget-local
  1569→ *
  1570→ * @param specDir - The .kspec directory path
  1571→ * @param sessionId - Session ID
  1572→ * @param maxPerCycle - Maximum tasks allowed per cycle
  1573→ * @returns The created budget
  1574→ */
  1575→export async function createBudget(
  1576→  specDir: string,
  1577→  sessionId: string,
  1578→  maxPerCycle: number,
  1579→): Promise<TaskBudget> {
  1580→  const budget: TaskBudget = {
  1581→    max_per_cycle: maxPerCycle,
  1582→    started_this_cycle: 0,
  1583→  };
  1584→  const validated = TaskBudgetSchema.parse(budget);
  1585→  const budgetPath = getSessionBudgetPath(specDir, sessionId);
  1586→  await writeBudgetAtomic(budgetPath, validated);
  1587→  return validated;
  1588→}
  1589→
  1590→/**
  1591→ * Read budget for a session.
  1592→ *
  1593→ * AC: @task-budget-enforcement ac-no-budget
  1594→ *
  1595→ * @param specDir - The .kspec directory path
  1596→ * @param sessionId - Session ID
  1597→ * @returns Budget or null if no budget configured (opt-in)
  1598→ */
  1599→export async function getBudget(
  1600→  specDir: string,
  1601→  sessionId: string,
  1602→): Promise<TaskBudget | null> {
  1603→  const budgetPath = getSessionBudgetPath(specDir, sessionId);
  1604→  try {
  1605→    const content = await fsPromises.readFile(budgetPath, "utf-8");
  1606→    const raw = JSON.parse(content);
  1607→    return TaskBudgetSchema.parse(raw);
  1608→  } catch {
  1609→    return null;
  1610→  }
  1611→}
  1612→
  1613→/**
  1614→ * Check whether the budget allows starting a new task.
  1615→ *
  1616→ * Returns an object with `allowed` boolean and context about the budget.
  1617→ * When no budget is configured, always allows (opt-in behavior).
  1618→ *
  1619→ * AC: @task-budget-enforcement ac-block-start
  1620→ * AC: @task-budget-enforcement ac-no-budget
  1621→ * AC: @task-budget-enforcement ac-no-session
  1622→ *
  1623→ * @param specDir - The .kspec directory path
  1624→ * @param sessionId - Session ID, or undefined if KSPEC_SESSION_ID not set
  1625→ * @returns Budget check result
  1626→ */
  1627→export async function checkBudget(
  1628→  specDir: string,
  1629→  sessionId: string | undefined,
  1630→): Promise<{
  1631→  allowed: boolean;
  1632→  reason?: string;
  1633→  budget?: TaskBudget;
  1634→}> {
  1635→  // AC: @task-budget-enforcement ac-no-session — no session means no check
  1636→  if (!sessionId) {
  1637→    return { allowed: true };
  1638→  }
  1639→
  1640→  const budget = await getBudget(specDir, sessionId);
  1641→
  1642→  // AC: @task-budget-enforcement ac-no-budget — no budget means no check
  1643→  if (!budget) {
  1644→    return { allowed: true };
  1645→  }
  1646→
  1647→  if (budget.started_this_cycle >= budget.max_per_cycle) {
  1648→    return {
  1649→      allowed: false,
  1650→      reason: `Task budget exhausted: ${budget.started_this_cycle}/${budget.max_per_cycle} tasks started this cycle. Wrap up current work and let the iteration end naturally without starting new tasks.`,
  1651→      budget,
  1652→    };
  1653→  }
  1654→
  1655→  return { allowed: true, budget };
  1656→}
  1657→
  1658→/**
  1659→ * Increment the budget counter after a task is successfully started.
  1660→ *
  1661→ * AC: @task-budget-enforcement ac-increment
  1662→ * AC: @task-budget-enforcement ac-atomic-write
  1663→ *
  1664→ * @param specDir - The .kspec directory path
  1665→ * @param sessionId - Session ID
  1666→ * @returns Updated budget, or null if no budget configured
  1667→ */
  1668→export async function incrementBudget(
  1669→  specDir: string,
  1670→  sessionId: string,
  1671→): Promise<TaskBudget | null> {
  1672→  const budget = await getBudget(specDir, sessionId);
  1673→  if (!budget) {
  1674→    return null;
  1675→  }
  1676→
  1677→  const updated: TaskBudget = {
  1678→    ...budget,
  1679→    started_this_cycle: budget.started_this_cycle + 1,
  1680→  };
  1681→  const validated = TaskBudgetSchema.parse(updated);
  1682→  const budgetPath = getSessionBudgetPath(specDir, sessionId);
  1683→  await writeBudgetAtomic(budgetPath, validated);
  1684→  return validated;
  1685→}
  1686→
  1687→/**
  1688→ * Reset the budget counter to 0 for a new cycle/iteration.
  1689→ *
  1690→ * Called by ralph at iteration boundaries. Single-writer guarantee:
  1691→ * ralph only resets between iterations when the agent is not running.
  1692→ *
  1693→ * AC: @task-budget-enforcement ac-reset
  1694→ * AC: @task-budget-enforcement ac-atomic-write
  1695→ *
  1696→ * @param specDir - The .kspec directory path
  1697→ * @param sessionId - Session ID
  1698→ * @returns Updated budget, or null if no budget configured
  1699→ */
  1700→export async function resetBudget(
  1701→  specDir: string,
  1702→  sessionId: string,
  1703→): Promise<TaskBudget | null> {
  1704→  const budget = await getBudget(specDir, sessionId);
  1705→  if (!budget) {
  1706→    return null;
  1707→  }
  1708→
  1709→  const updated: TaskBudget = {
  1710→    ...budget,
  1711→    started_this_cycle: 0,
  1712→  };
  1713→  const validated = TaskBudgetSchema.parse(updated);
  1714→  const budgetPath = getSessionBudgetPath(specDir, sessionId);
  1715→  await writeBudgetAtomic(budgetPath, validated);
  1716→  return validated;
  1717→}
